  blade: [116, 152, 70], bladeW: [26, 12, -1], tuftN: 1, tuftFloor: 1,
  treeMix: [0.42, 0.72], treeN: 1,
  // r3: paintCanopy already bakes a 5:1 top-to-underside AO ramp, so the gradient was never
