  h += 0.44 * (fbmz(x * 0.165 + 2.9, z * 0.165 + 5.7, 2) - 0.5) * 2;
  const u = ringU(x, z);
  h += 6.2 * sstep(0.34, 0.94, u);       // ground lifts toward the cliff feet
