  h += rise * brk * (fbmz(x * 0.098 + 41.7, z * 0.098 + 7.3, 3) - 0.5) * 13;    // ~10u buttresses
  h += rise * brk * (fbmz(x * 0.165 + 12.3, z * 0.165 + 88.7, 3) - 0.5) * 12;   // ~6u ledges & ribs
  h += rise * brk * (fbmz(x * 0.44 + 5.1, z * 0.44 + 2.3, 2) - 0.5) * 4.2;      // ~2.3u breakage
