      g.fillStyle = '#241a10'; g.beginPath(); g.arc(ex - sx * S * 0.014, ey + S * 0.006, S * 0.036, 0, 7); g.fill();
      g.fillStyle = 'rgba(14,8,4,.88)'; g.fillRect(ex - S * 0.098, ey - S * 0.052, S * 0.196, S * 0.030);
