  const paid = Math.max(tw.bondPaid, other ? other.bondPaid : 0);
  tw.bond = 0; tw.bondEl = ''; tw.bondPaid = 0;
  if (other) { other.bond = 0; other.bondEl = ''; other.bondPaid = 0; }
  if (pay && paid > 0) state.gold += Math.round(paid * RB_REFUND);
