  // one cheese this system could ship. A smite there is just a smite.
  if (P.gate) for (const r of G.spawnRoutes) {
    G.pathPos(0, _cp, 0, r);
    if (Math.hypot(x - _cp.x, z - _cp.z) < P.gate) return { ok: false, why: 'gate', reason: L('cp.gate') };
  }
