    const age = t - D[o];
    if (age < 0 || age >= life) continue;
    const k = D[o + 9], gv = D[o + 8];
    let A, Bg, ev;
    if (k > 1e-3) { ev = Math.exp(-k * age); A = (1 - ev) / k; Bg = (age - A) / k; }
    else { ev = 1; A = age; Bg = age * age * 0.5; }
