    aP[j + 1] = D[o + 3] + D[o + 6] * A - gv * Bg;
    aP[j + 2] = D[o + 4] + D[o + 7] * A;
    aV[j] = D[o + 5] * ev; aV[j + 1] = D[o + 6] * ev - gv * A; aV[j + 2] = D[o + 7] * ev;
    aS[j2] = s; aS[j2 + 1] = s * D[o + 21];
