const SMK = () => (er() < 0.5 ? T_SMOKE : T_WISP);
const _bc = new THREE.Color();

// ══════════════════════ EFFECT AUTHORING ═════════════════════════════════════

// ── generic hit spray. SIM contract: y is relative to the ground. ─────────────
// SIM calls this for three different events (arrow/bolt hit, enemy killed, knight
