  g.fillStyle = 'rgba(0,0,0,.34)';
  poly(g, [x - 1.15 * s, y + 2.2 * s, x - 0.25 * s, y + 2.2 * s, x - 0.55 * s, y + 5.9 * s, x - 1.65 * s, y + 5.9 * s], 'rgba(0,0,0,.34)');
  g.fillStyle = PAL.iron[3]; g.beginPath(); g.arc(x, y + 7.1 * s, 1.5 * s, 0, 7); g.fill();  // helm
