UI.deselect = () => { state.selTower = -1; sellArm = false; $('towerMenu').classList.add('hidden'); UI.buildMenu(); };
// FIX4-UI §4 — ONE CONTAINER, ONE TYPE SYSTEM, ONE ANCHOR. Placement used to speak twice, in
