UI.resumeOffer = resumeOffer;
$('btnBack').onclick = () => { $('maps').classList.add('hidden'); $('title').classList.remove('hidden'); Audio.play('ui'); };
// SPEC6 §B — the council opens off the chooser and returns to it, so it never becomes a
