      const df = Math.max(12, bd - 24);
      G.pathPos(df, _v3);
      const mx = _v3.x, mz = _v3.z, gy = G.groundY(mx, mz), tn = G.pathTan(df);
      const c = SHOT_PRESETS._wardfx.cam, ZM = +(P.get('zm') || 24);
